def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count opponent cooperations and defects
    opp_c = 0
    for h in history:
        if h[1] == 'C':
            opp_c += 1
    opp_d = n - opp_c

    # Recent window of 8 (or all so far)
    w = 8 if n >= 8 else n
    recent = history[-w:]
    rec_c = 0
    for h in recent:
        if h[1] == 'C':
            rec_c += 1
    rec_d = w - rec_c

    # Consecutive opponent defections at tail
    tail_d = 0
    for h in reversed(history):
        if h[1] == 'D':
            tail_d += 1
        else:
            break

    # Consecutive opponent cooperations at tail
    tail_c = 0
    for h in reversed(history):
        if h[1] == 'C':
            tail_c += 1
        else:
            break

    # First moves: cooperate, then mirror a first defection
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    remaining = 100 - n

    # Endgame: exploit a cooperative opponent
    if remaining <= 2:
        if opp_c * 4 >= n * 3:
            return 'D'
        if rec_c * 2 >= w:
            return 'D'
        return 'C'

    # If opponent has defected many times, mostly defect
    if opp_d * 3 > n:
        # But try to reopen once in a while
        if tail_d >= 3:
            if rng.random() < 0.05:
                return 'C'
            return 'D'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent currently in a defection streak
    if tail_d >= 1:
        # Longer defection streaks -> hard retaliation
        if tail_d >= 3:
            return 'D'
        # Short isolated defection: retaliate, but forgive non-trivially
        if tail_c == 0 and tail_d == 1:
            # Check previous runs to see if a single defection is common
            if opp_d <= 2:
                # very cooperative opponent, forgive once
                if rng.random() < 0.6:
                    return 'C'
                return 'D'
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last. Try to detect hostile/alternating patterns.
    if n >= 4:
        alt = True
        recent4 = history[-4:]
        for i in range(1, 4):
            if recent4[i][1] == recent4[i-1][1]:
                alt = False
                break
        if alt:
            return 'D'

    # If opponent has been almost perfectly cooperative, cooperate but occasionally probe.
    if opp_d == 0:
        if n >= 2 and n % 11 == 0:
            return 'D'
        return 'C'

    # Recent hostility detection: opponent's recent defect rate is much worse than baseline?
    if w >= 5 and rec_d * 10 >= w * 4:
        # strong recent defecting trend
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    # If opponent just defected earlier and came back, cooperate to rebuild.
    if tail_c >= 1 and n >= 2 and history[-1][1] == 'C':
        # If we might have just retaliated and they forgave, cooperate more.
        if n >= 2 and history[-2][1] == 'D' and history[-1][1] == 'C':
            return 'C'

    # Mostly cooperate against a reasonably cooperative opponent, with occasional probing.
    if opp_c * 4 >= n * 3:
        if rng.random() < 0.06 and remaining > 5:
            return 'D'
        return 'C'

    if opp_c * 2 >= n:
        if rng.random() < 0.10:
            return 'D'
        return 'C'

    # Fallback: cooperate if they just cooperated.
    return 'C'
